
(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s);
const icons={computer:'M3 4h18v13H3z M1 21h22 M9 17v4m6-4v4',keyboard:'M2 6h20v13H2z M5 10h1m3 0h1m3 0h1m3 0h1 M5 14h1m3 0h1m3 0h1m3 0h1 M8 17h8',tablet:'M6 2h12v20H6z M11 18h2',audio:'M3 14v-3a9 9 0 0 1 18 0v3 M3 12h4v9H3z M17 12h4v9h-4z',phone:'M7 2h10v20H7z M10 18h4',coffee:'M3 7h13v8a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5z M16 8h2a3 3 0 0 1 0 6h-2 M6 2v2m4-2v2m4-2v2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',check:'m5 12 4 4L19 6',edit:'m16 3 5 5-12 12H4v-5z M13 6l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7m4-7v7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3 1 3 1v4l-3 2-1 3-1 3h-4l-2-3-3-1-3-1v-4l3-2 1-3z',moon:'M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',close:'m6 6 12 12M6 18 18 6',help:'M12 17h.01 M9 9a3 3 0 1 1 4 3c-1 0-1 1-1 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',box:'m3 7 9-5 9 5v11l-9 4-9-4z M3 7l9 5 9-5M12 12v10',chevron:'m9 5 7 7-7 7'};
const icon=n=>`<svg class="od-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seeds=[{id:'mac',name:'MacBook Pro 14″',category:'computer',price:14999,date:'2025-06-18',daily:20,note:'',currency:'CNY'},{id:'key',name:'Keychron K2',category:'keyboard',price:999,date:'2024-02-13',daily:2,note:'',currency:'CNY'},{id:'kindle',name:'Kindle Paperwhite',category:'tablet',price:998,date:'2021-03-10',daily:null,note:'',currency:'CNY'},{id:'air',name:'AirPods Pro 2',category:'audio',price:1899,date:'2025-08-23',daily:4,note:'',currency:'CNY'},{id:'phone',name:'iPhone 17',category:'phone',price:5999,date:'2026-08-03',daily:15,note:'',currency:'CNY'},{id:'coffee',name:'德龙咖啡机',category:'coffee',price:893,date:'2026-06-23',daily:6,note:'',currency:'CNY'}];
const page=document.body.dataset.start||'home';
const model=createPaybackModel({key:page==='empty'?'payback-design-v2-empty':'payback-design-v2',seeds:page==='empty'?[]:seeds});
let state=model.snapshot(),language='zh-CN';
function sync(){state=model.snapshot();language=state.preferences.language==='system'?(navigator.language.toLowerCase().startsWith('zh')?'zh-CN':'en'):state.preferences.language;document.documentElement.lang=language;document.title=language==='en'?'Payback — Make every day count':'Payback — 让投入用得值得';}
sync();
const t=(zh,en)=>language==='en'?en:zh;
const locale=()=>language==='en'?'en-US':'zh-CN';
const number=v=>new Intl.NumberFormat(locale()).format(v);
const money=(v,c='CNY',digits=2)=>new Intl.NumberFormat(locale(),{style:'currency',currency:c,minimumFractionDigits:digits,maximumFractionDigits:digits}).format(v);
const date=v=>new Intl.DateTimeFormat(locale(),{year:'numeric',month:'short',day:'numeric'}).format(new Date(v+'T12:00:00'));
const categoryNames={computer:['电脑','Computer'],keyboard:['配件','Accessory'],tablet:['平板 / 阅读器','Tablet / e-reader'],audio:['音频','Audio'],phone:['手机','Phone'],coffee:['家电','Appliance'],box:['其他','Other']};
const currencyNames={CNY:['人民币','Chinese yuan'],USD:['美元','US dollar'],EUR:['欧元','Euro'],JPY:['日元','Japanese yen'],GBP:['英镑','Pound sterling'],HKD:['港元','Hong Kong dollar'],TWD:['新台币','New Taiwan dollar'],KRW:['韩元','South Korean won'],SGD:['新加坡元','Singapore dollar'],AUD:['澳元','Australian dollar'],CAD:['加元','Canadian dollar'],CHF:['瑞士法郎','Swiss franc']};
const categoryLabel=v=>t(...(categoryNames[v]||categoryNames.box));
const options=(map,value)=>Object.entries(map).map(([v,n])=>`<option value="${v}" ${value===v?'selected':''}>${map===currencyNames?v+' · ':''}${esc(t(...n))}</option>`).join('');
let selected=page==='device'&&state.devices.some(d=>d.id==='key')?'key':state.devices[0]?.id;
let view=page==='settings'?'settings':'devices',mobile=['library','empty','home'].includes(page)?'list':'detail',sort='added',limit=50,editing=null,returnFocus=null,saving=false,toastTimer,lastDeleted=null,importPlan=null,pendingFile=null,agentExample=null;
const app=$('#app');
const media=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(){document.documentElement.classList.toggle('dark',state.preferences.theme==='dark'||(state.preferences.theme==='system'&&media.matches));}
media.addEventListener('change',applyTheme);
function errorText(code){return ({NAME_REQUIRED:t('请填写不超过 120 字符的设备名称。','Enter a device name of up to 120 characters.'),INVALID_AMOUNT:t('金额须大于 0、不超过 10,000,000，最多两位小数。','Use an amount above 0 and up to 10,000,000, with at most two decimal places.'),INVALID_DATE:t('请选择 1900 年至今天之间的有效日期。','Choose a valid date between 1900 and today.'),INVALID_CURRENCY:t('请选择支持的货币。','Choose a supported currency.'),INVALID_CATEGORY:t('请选择有效分类。','Choose a valid category.'),INVALID_NOTE:t('备注不得超过 2,000 字符。','Notes must be no longer than 2,000 characters.'),INVALID_BACKUP:t('备份格式、版本或记录不合法，未更改当前数据。','The backup format, version, or records are invalid. Your data has not changed.'),STALE_PREVIEW:t('数据已变化，请重新预览后再提交。','Data has changed. Preview again before committing.'),EXTERNAL_CHANGE:t('其他页面已更新数据。请先导出当前会话备份，再重新加载页面。','Another page changed the data. Export this session before reloading.'),DAMAGED_STORAGE:t('已有存储无法读取。请先下载原始数据，再用有效备份恢复。','Existing storage could not be read. Download the original data, then restore a valid backup.'),BUSY:t('请先完成或关闭当前操作。','Finish or close the current operation first.'),NOT_FOUND:t('未找到这条设备记录。','This device could not be found.'),LIMIT_REACHED:t('设备或最近删除记录已达到 2,000 条上限，请先备份。','The device or deleted-record limit of 2,000 has been reached. Back up your data.'),INVALID_TOKEN:t('预览凭据无效，请重新预览。','Invalid preview token. Preview again.'),EXPIRED_TOKEN:t('预览已过期，请重新预览。','This preview expired. Preview again.'),WRITES_DISABLED:t('请先在设置中开启自动化写入。','Enable automation writes in Settings first.')})[code]||t('无法完成操作，当前输入已保留。','The operation could not be completed. Your input has been kept.');}
function notify(message,undo=false){const box=$('#toast');box.innerHTML=`<span>${esc(message)}</span>${undo?`<button class="toast-action" data-action="undo">${t('撤销','Undo')}</button>`:''}`;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,undo?10000:6000);}
function storageMessage(){return state.storage.persistent?t('已保存在此浏览器','Saved in this browser'):t('仅保留在本次会话，请导出备份','Session only — export a backup');}
function refresh(){sync();if(!state.devices.some(d=>d.id===selected))selected=state.devices[0]?.id;applyTheme();render();}
function current(){return state.devices.find(d=>d.id===selected);}
function execute(request){const plan=model.preview(request);if(!plan.ok)return plan;return model.commit(plan.data.token);}
function handleResult(result,message){if(!result.ok){notify(errorText(result.error.code));return false;}if(result.data.selectedId!==null)selected=result.data.selectedId;refresh();notify(`${message} · ${storageMessage()}`);return true;}
function render(){
  applyTheme();app.dataset.mobile=view==='settings'?'settings':mobile;app.classList.toggle('is-empty',state.devices.length===0&&view==='devices');
  app.innerHTML=`<aside class="sidebar" id="sidebar"></aside><section class="workspace"><header class="topbar"><div class="od-row od-fill"><button class="icon-button mobile-back" data-action="back" aria-label="${t('返回设备列表','Back to devices')}">${icon('back')}</button><span class="breadcrumb">${view==='settings'?t('偏好设置','Preferences'):t('我的设备','My devices')}</span></div><div class="actions"><button class="icon-button" data-action="settings" aria-label="${t('打开设置','Open settings')}" title="${t('设置','Settings')}">${icon('settings')}</button><button class="icon-button" data-action="theme" aria-label="${t('切换亮暗主题','Toggle light and dark appearance')}">${icon(document.documentElement.classList.contains('dark')?'sun':'moon')}</button><button class="button primary" data-action="add">${icon('plus')}${t('添加设备','Add device')}</button></div></header><div id="storage-warning" class="storage-warning" ${state.storage.persistent?'hidden':''} role="status">${state.storage.damaged?esc(errorText('DAMAGED_STORAGE')):t('当前数据仅在本次会话中可用，请及时导出备份。','Your data is available for this session only. Export a backup to keep it.')} <button class="text-btn" data-action="${state.storage.damaged?'export-original':'export'}">${state.storage.damaged?t('下载原始数据','Download original data'):t('导出备份','Export backup')}</button></div><main class="content ${view==='settings'?'settings':''}" id="content"></main></section>`;
  renderSidebar();if(view==='settings')renderSettings();else renderDetail();
}
function renderSidebar(){
  const ds=state.devices.filter(d=>d.currency===state.preferences.currency),sum=ds.reduce((n,d)=>n+d.price,0),daily=ds.reduce((n,d)=>n+model.metrics(d).cost,0);
  let list=[...state.devices];if(sort==='date')list.sort((a,b)=>b.date.localeCompare(a.date));if(sort==='cost')list.sort((a,b)=>a.currency.localeCompare(b.currency)||model.metrics(b).cost-model.metrics(a).cost);
  $('#sidebar').innerHTML=`<header class="side-heading"><div class="brand"><span class="brandmark">${icon('arrow')}</span>Payback</div><button class="icon-button" data-action="help" aria-label="${t('原型说明','About this prototype')}">${icon('help')}</button></header><div class="sidebar-scroll od-scroll"><section class="sidebar-summary"><p class="eyebrow">${t('设备投入','Device investment')} · ${esc(state.preferences.currency)}</p><p class="summary-value num">${money(sum,state.preferences.currency,0)}</p><p class="summary-caption">${t('让每一份投入，都用得值得。','Make every purchase worth keeping.')}</p><div class="mini-stats"><div class="od-stat"><strong class="num">${money(daily,state.preferences.currency)}</strong><span>${t('合计每日成本','Daily cost total')}</span></div><div class="od-stat"><strong>${number(state.devices.length)}</strong><span>${t('记录中的设备','Devices tracked')}</span></div></div>${ds.length!==state.devices.length?`<p class="summary-caption">${t('仅汇总当前默认货币。每日成本排序按币种分组，不换算汇率。','Totals use the default currency. Daily costs are sorted within each currency, without conversion.')}</p>`:''}</section><section><div class="side-title"><h2>${t('我的设备','My devices')}</h2><select class="sort-select" aria-label="${t('设备排序','Sort devices')}" id="sort"><option value="added" ${sort==='added'?'selected':''}>${t('加入顺序','Added order')}</option><option value="date" ${sort==='date'?'selected':''}>${t('最近购买','Newest purchase')}</option><option value="cost" ${sort==='cost'?'selected':''}>${t('每日成本','Daily cost')}</option></select></div><div class="device-list">${list.length?list.slice(0,limit).map(d=>{const m=model.metrics(d),done=m.target&&m.remaining===0;return `<button class="device-row ${d.id===selected&&view==='devices'?'active':''}" data-device="${esc(d.id)}" aria-pressed="${d.id===selected&&view==='devices'}"><span class="device-icon">${icon(d.category)}</span><span class="od-field od-fill"><span class="name od-truncate">${esc(d.name)}</span><span class="sub">${money(m.cost,d.currency)}${t(' / 天',' / day')}${done?' · '+t('已回本','Goal met'):''}</span></span>${done?'<span class="state-dot" aria-hidden="true"></span>':''}</button>`;}).join(''):`<p class="muted">${t('还没有设备，添加一台开始记录。','No devices yet. Add one to get started.')}</p>`}</div>${list.length>limit?`<button class="button" data-action="more">${t('再显示 50 台','Show 50 more')}</button>`:''}<button class="button side-add" data-action="add">${icon('plus')}${t('添加设备','Add device')}</button></section></div><footer class="side-foot"><button class="settings-entry ${view==='settings'?'active':''}" data-action="settings" aria-current="${view==='settings'?'page':'false'}">${icon('settings')}<span>${t('设置','Settings')}</span><span class="settings-language">${language==='en'?'EN':'中文'}</span></button><p class="prototype-label">${t('交互原型 · 示例数据','Interactive prototype · Sample data')}</p><nav class="side-links" aria-label="${t('原型页面','Prototype pages')}">${[['library',t('设备库','Library')],['device',t('已回本','Goal met')],['empty',t('空库','Empty')],['form',t('添加','Add')],['settings',t('设置','Settings')]].map(([p,label])=>`<a href="${page==='home'?'prototype/':''}${p}.html">${label}</a>`).join('')}</nav></footer>`;
}
function chart(d,m){const sample=Array.from({length:65},(_,i)=>{const f=i/64,day=1+f*(m.held-1);return{x:8+f*744,y:8+(1-1/day)*144};});const path=sample.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ');return `<svg class="chart" viewBox="0 0 760 180" role="img" aria-label="${esc(t('每日成本随持有时间下降，当前为','Daily cost decreases with ownership time. Current cost: ')+money(m.cost,d.currency))}"><path class="chart-fill" d="${path} L752,170 L8,170 Z"/><line class="axis" x1="8" y1="80" x2="752" y2="80"/><line class="axis" x1="8" y1="170" x2="752" y2="170"/><path class="chart-line" d="${path}"/><circle cx="752" cy="${sample[64].y}" r="4" fill="var(--accent)"/></svg>`;}
function renderDetail(){
  const d=current(),c=$('#content');
  if(!d){c.innerHTML=`<div class="empty"><div class="empty-symbol">${icon('box')}</div><h1>${t('从第一台设备开始','Start with your first device')}</h1><p>${t('记下价格和购买日期，看看它的每日成本如何一点点降下来。','Record its price and purchase date, and watch its daily cost fall over time.')}</p><button class="button primary" data-action="add">${icon('plus')}${t('添加第一台设备','Add your first device')}</button><p class="example">${t('一台 999 元的键盘，用满 1,000 天，每天成本约 1 元。','A CNY 999 keyboard costs about CNY 1 a day after 1,000 days.')}</p></div>`;return;}
  const m=model.metrics(d),earned=m.target&&m.remaining===0;
  c.innerHTML=`<div class="device-head"><div class="od-fill"><p class="eyebrow">${esc(categoryLabel(d.category))} · ${t(`已陪伴 ${number(m.held)} 天`,`${number(m.held)} days together`)}</p><h1>${esc(d.name)}</h1><p class="meta">${money(d.price,d.currency)} · ${t('购于','Purchased')} ${date(d.date)}</p></div><div class="actions"><button class="icon-button" data-action="edit" aria-label="${t('编辑设备','Edit device')}">${icon('edit')}</button><button class="icon-button" data-action="delete" aria-label="${t('删除设备','Delete device')}">${icon('trash')}</button></div></div><section class="hero" aria-label="${t('成本与回本目标','Daily cost and personal value goal')}"><div><p class="hero-label">${t('现在的每日成本','Your daily cost today')}</p><p class="hero-number num">${money(m.cost,d.currency)}<span class="unit">${t(' / 天',' / day')}</span></p><p class="muted hero-caption">${t('每多用一天，成本就再轻一点。','Another day of use. A little less per day.')}</p></div><div class="goal">${m.target?`<p class="hero-label">${earned?t('你的回本目标','Your personal value goal'):t('距离回本目标','Until your value goal')}</p><p class="goal-number ${earned?'earned':''}">${earned?`${icon('check')} ${t('已回本','Goal met')}`:`${number(m.remaining)} <span>${t('天','days')}</span>`}</p><div class="bar ${earned?'earned':''}" role="progressbar" aria-label="${t('回本进度','Value goal progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(m.progress)}"><i style="width:${m.progress.toFixed(2)}%"></i></div><p class="muted">${t(`按每天 ${money(d.daily,d.currency)} 的个人使用价值计算`,`Based on your personal value of ${money(d.daily,d.currency)} per day`)}</p>${earned?`<p class="muted">${t(`已超出购买成本 ${money(m.extra,d.currency)}`,`Personal value beyond purchase cost: ${money(m.extra,d.currency)}`)}</p>`:''}`:`<p class="hero-label">${t('你的回本目标','Your personal value goal')}</p><p class="goal-question">${t('什么价位，你觉得值得？','What feels worth it to you?')}</p><p class="muted">${t('设定每天愿意付的金额，看看何时达到自己的目标。','Set what you would pay per day to see when your purchase feels worthwhile.')}</p><button class="text-btn accent-link" data-action="edit">${t('设置每日价值','Set daily value')} ${icon('arrow')}</button>`}</div></section><section class="section chart-wrap"><div class="section-head"><h2>${t('成本，一天比一天轻','Less per day, every day')}</h2><small>${t(`${number(m.held)} 天的变化`,`${number(m.held)} days of ownership`)}</small></div>${chart(d,m)}<div class="chart-labels"><span>${t('购买当天','Day one')} · ${money(d.price,d.currency)}</span><span>${t('今天','Today')} · ${money(m.cost,d.currency)}</span></div><p class="chart-note">${t('每日成本 = 购买价格 ÷ 持有天数','Daily cost = purchase price ÷ days owned')}</p></section><div class="bottom-grid"><section class="section"><div class="section-head"><h2>${t('一路的小里程碑','Small milestones')}</h2><span class="muted">${[100,365,1000].filter(n=>m.held>=n).length} / 3</span></div><div class="milestones">${[100,365,1000].map(n=>`<div class="milestone"><span class="${m.held>=n?'check':'future'}">${icon(m.held>=n?'check':'chevron')}</span><span class="label">${t(`陪伴 ${number(n)} 天`,`${number(n)} days together`)}</span><small>${m.held>=n?t('已达成','Reached'):t(`还差 ${number(n-m.held)} 天`,`${number(n-m.held)} days to go`)}</small></div>`).join('')}</div><details class="method milestone-details"><summary>${t('查看成本里程碑','See daily cost milestones')}</summary>${[10,5,2,1,.5].map(n=>`<p>${m.cost<n?t('已达成','Reached'):t('未达成','Not yet')} · ${t('日均低于','Below')} ${money(n,d.currency)}${t(' / 天',' / day')}</p>`).join('')}</details></section><section class="section"><h2>${t('怎样理解回本？','What does “goal met” mean?')}</h2><div class="method method-body"><p>${t('这里的回本，是达到你心中“用得值得”的目标。','Your goal is reached when the accumulated personal value matches what you paid.')}</p><p>${t('它按你设定的每日价值累计，不代表真实收入或转售价值。','It uses the daily value you set. It is not income or resale value.')}</p><details class="method-details"><summary>${t('计算方式','How it is calculated')}</summary><p>${t('回本天数 = 购买价格 ÷ 每日价值，向上取整。持有天数从购买当天算起。','Days to goal = purchase price ÷ daily value, rounded up. The purchase date counts as day one.')}</p><p>${t('修改每日价值后，将按新标准重新计算全部持有时间。','Changing daily value recalculates the whole ownership period.')}</p></details></div></section></div>${d.note?`<section class="section"><h2>${t('设备备注','Device notes')}</h2><p class="muted notes">${esc(d.note)}</p></section>`:''}`;
}
const settingRow=(label,help,control,id='')=>`<div class="setting-row"><div class="od-field od-fill">${id?`<label for="${id}">${label}</label>`:`<h3>${label}</h3>`}<p>${help}</p></div><div class="setting-control">${control}</div></div>`;
function renderSettings(){
  const p=state.preferences;
  $('#content').innerHTML=`<header class="settings-title"><p class="eyebrow">${t('你的 Payback','YOUR PAYBACK')}</p><h1>${t('设置','Settings')}</h1><p class="muted">${t('习惯、数据与操作权限，都在这里。','Your preferences, data, and automation controls.')}</p></header><nav class="settings-sections" aria-label="${t('设置分组','Settings sections')}"><a href="#general">${t('通用','General')}</a><a href="#data">${t('数据','Data')}</a><a href="#automation">${t('自动化','Automation')}</a></nav><section class="settings-group" id="general"><h2>${t('语言与外观','Language & appearance')}</h2><div class="setting-surface">${settingRow(t('界面语言','Language'),t('切换全部界面与日期、金额格式，设备名称及备注保持原文。','Updates the interface and formatting. Device names and notes stay as entered.'),`<select id="language"><option value="system" ${p.language==='system'?'selected':''}>${t('跟随系统','System default')}</option><option value="zh-CN" ${p.language==='zh-CN'?'selected':''}>简体中文</option><option value="en" ${p.language==='en'?'selected':''}>English</option></select>`,'language')}${settingRow(t('外观','Appearance'),t('选择舒适的阅读方式。','Choose what feels comfortable to read.'),`<select id="appearance">${[['system',t('跟随系统','System default')],['light',t('浅色','Light')],['dark',t('深色','Dark')]].map(([v,n])=>`<option value="${v}" ${p.theme===v?'selected':''}>${n}</option>`).join('')}</select>`,'appearance')}${settingRow(t('默认货币','Default currency'),t('用于新增与汇总；已有记录不换算。','Used for new devices and totals. Existing amounts are not converted.'),`<select id="default-currency">${options(currencyNames,p.currency)}</select>`,'default-currency')}</div></section><section class="settings-group" id="data"><h2>${t('数据与恢复','Data & recovery')}</h2><div class="setting-surface">${settingRow(t('保存位置','Storage'),state.storage.damaged?errorText('DAMAGED_STORAGE'):state.storage.persistent?t('数据保存在此浏览器。清理浏览器数据会移除记录，请定期备份。','Data is saved in this browser. Clearing browser data removes it; keep a backup.'):t('本地存储不可用，修改仅保留到本次会话结束。','Local storage is unavailable. Changes last for this session only.'),`<span class="status-pill">${state.storage.persistent?t('浏览器本地','Browser local'):t('仅本次会话','Session only')}</span>`)}${settingRow(t('备份导出','Export backup'),t('导出设备、最近删除记录及偏好，不包含自动化写入许可。','Includes devices, deleted records, and preferences. Automation permission is excluded.'),`<button class="button" data-action="export">${t('导出 JSON','Export JSON')}</button>`)}${settingRow(t('从备份恢复','Restore backup'),t('先校验文件并展示替换范围，确认后再恢复。','Validate the file and review what will be replaced before restoring.'),`<button class="button" data-action="import">${t('选择备份','Choose backup')}</button>`)}${state.storage.damaged?settingRow(t('原始数据','Original data'),t('先保存无法读取的原始内容，避免覆盖后丢失。','Keep the unreadable original before replacing it with a backup.'),`<button class="button" data-action="export-original">${t('下载原始数据','Download original')}</button>`):''}${settingRow(t('最近删除','Recently deleted'),t(`${number(state.trash.length)} 台设备可恢复；不会自动清空。`,`${number(state.trash.length)} devices can be restored. Nothing is purged automatically.`),`<button class="button" data-action="trash">${t('查看与恢复','View & restore')}</button>`)}${settingRow(t('跨设备同步','Cross-device sync'),t('原型未连接网盘或服务器，导出的备份可手动转移。','This prototype has no cloud or folder sync. Transfer exported backups manually.'),`<span class="muted">${t('未接入','Not connected')}</span>`)}</div></section><section class="settings-group" id="automation"><h2>${t('Agent 与自动化','Agent & automation')}</h2><div class="setting-surface">${settingRow(t('结构化查询','Structured queries'),t('当前页面支持读取设备、成本、回本目标与接口说明，无需模拟点击。','Read devices, daily costs, goals, and API information without simulated clicks.'),`<button class="button" data-action="agent-help">${t('调用说明','API guide')}</button>`)}${settingRow(t('允许自动化写入','Allow automation writes'),t('默认关闭，仅本次页面有效。开启后可先预览变更，再凭预览标识提交。','Off by default and limited to this page session. Enabled writes require a preview token before committing.'),`<input type="checkbox" id="automation-enabled" class="switch-input" ${state.automationEnabled?'checked':''}>`,'automation-enabled')}<p class="sync-info">${t('此接口仅服务当前浏览器原型，不是正式产品 CLI、MCP 或远程服务。同一页面脚本可访问它，开关不构成安全隔离。','This API serves this browser prototype only. It is not a product CLI, MCP server, or remote service. Same-page scripts can access it; the toggle is not a security boundary.')}</p></div></section><section class="settings-group"><h2>${t('关于 Payback','About Payback')}</h2><p class="muted">${t('记录设备的每日成本，看见时间带来的使用价值。','Track the daily cost of your devices and the value of time spent using them.')}</p><button class="text-btn accent-link" data-action="help">${t('原型与数据说明','Prototype & data information')} ${icon('arrow')}</button></section>`;
}
function focusMain(){const h=$('#content h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function showModal(html){returnFocus=document.activeElement;$('#modal').innerHTML=html;$('#modal').showModal();}
function closeModal(){if(saving)return;$('#modal').close();importPlan=null;pendingFile=null;const f=returnFocus?.isConnected?returnFocus:$('[data-action="settings"]');f?.focus();}
function dialogFrame(title,body,footer='',large=false){return `<header class="dialog-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="${t('关闭','Close')}">${icon('close')}</button></header><div class="dialog-body ${large?'help-copy':''}">${body}</div>${footer?`<footer class="dialog-foot">${footer}</footer>`:''}`;}
function field(id,label,input,help=''){return `<div class="field"><label for="${id}">${label}</label>${input}${help?`<small id="${id}-help">${help}</small>`:''}<span class="field-error" id="${id}-error" hidden></span></div>`;}
function openEditor(d=null){
  editing=d?.id||null;
  const input=(id,value,type='text',more='')=>`<input id="${id}" name="${id}" type="${type}" value="${esc(value)}" aria-describedby="${id}-error" ${more}>`;
  showModal(dialogFrame(d?t('编辑设备','Edit device'):t('添加设备','Add device'),`<div id="form-error" class="dialog-error" role="alert" hidden></div><form id="device-form" novalidate>${field('name',t('设备名称 · 必填','Device name · required'),input('name',d?.name||'','text','required maxlength="120" autocomplete="off"'))}<div class="form-grid">${field('price',t('购买价格 · 必填','Purchase price · required'),input('price',d?.price??'','text','required inputmode="decimal"'))}${field('currency',t('货币','Currency'),`<select id="currency">${options(currencyNames,d?.currency||state.preferences.currency)}</select>`)}${field('date',t('购买日期 · 必填','Purchase date · required'),input('date',d?.date||model.today(),'date',`required max="${model.today()}" min="1900-01-01"`))}${field('category',t('分类','Category'),`<select id="category">${options(categoryNames,d?.category||'computer')}</select>`)}</div><section class="form-section"><h3>${t('你的回本目标','Your personal value goal')}</h3><label class="check-label"><input id="goal-enabled" type="checkbox" ${!d||d.daily?'checked':''}>${t('设置每天愿意付的金额','Set what you would pay per day')}</label><div id="daily-field" ${d&&!d.daily?'hidden':''}>${field('daily',t('每日价值','Daily value'),input('daily',d?.daily??'','text','inputmode="decimal"'),t('例如每天 2 元。累计使用价值达到购买价格时，视为回本。','For example, 2 units per day. Your goal is met when accumulated value reaches the purchase price.'))}</div></section><details ${d?.note?'open':''}><summary>${t('添加备注（可选）','Notes (optional)')}</summary>${field('note',t('备注','Notes'),`<textarea id="note" maxlength="2000">${esc(d?.note||'')}</textarea>`)}</details></form>`,`<button class="button" data-action="close-modal">${t('取消','Cancel')}</button><button class="button primary" data-action="save" id="save">${t('保存设备','Save device')}</button>`));$('#name').focus();
}
function editorInput(){const raw=$('#price').value.trim(),daily=$('#daily').value.trim();const parse=v=>/^\d+(\.\d{1,2})?$/.test(v)?Number(v):NaN;return {id:editing||'new-device',name:$('#name').value,price:parse(raw),currency:$('#currency').value,date:$('#date').value,category:$('#category').value,daily:$('#goal-enabled').checked?parse(daily):null,note:$('#note').value};}
function validateEditor(only=null){const result=model.validateDevice(editorInput()),errors=result.ok?{}:result.error.fields||{};for(const id of only?[only]:['name','price','date','daily','note','currency','category']){const out=$('#'+id+'-error'),el=$('#'+id);if(!out||!el)continue;out.textContent=errors[id]?errorText(errors[id]):'';out.hidden=!errors[id];el.setAttribute('aria-invalid',errors[id]?'true':'false');}return result;}
function saveEditor(){
  if(saving)return;const checked=validateEditor();if(!checked.ok){const first=Object.keys(checked.error.fields||{})[0];$('#'+first)?.focus();return;}
  const {id,...device}=checked.data;const request=editing?{action:'update',id:editing,patch:device}:{action:'create',device};
  const plan=model.preview(request);if(!plan.ok){$('#form-error').textContent=errorText(plan.error.code);$('#form-error').hidden=false;return;}
  saving=true;$('#modal').querySelectorAll('button,input,select,textarea').forEach(n=>n.disabled=true);$('#save').textContent=t('正在保存…','Saving…');
  setTimeout(()=>{const result=model.commit(plan.data.token);saving=false;$('#modal').querySelectorAll('button,input,select,textarea').forEach(n=>n.disabled=false);if(!result.ok){$('#form-error').textContent=errorText(result.error.code);$('#form-error').hidden=false;$('#save').textContent=t('重试保存','Retry save');return;}selected=result.data.selectedId;view='devices';mobile='detail';closeModal();refresh();focusMain();notify(t('设备已保存','Device saved')+' · '+storageMessage());},360);
}
function openDelete(){const d=current();if(!d)return;showModal(dialogFrame(t('删除这台设备？','Delete this device?'),`<p class="dialog-copy">${esc(d.name)}</p><p class="muted dialog-description">${t('设备将移到最近删除，记录与目标均可恢复。','The device will move to Recently deleted. Its record and goal can be restored.')}</p>`,`<button class="button" data-action="close-modal" autofocus>${t('保留设备','Keep device')}</button><button class="button danger" data-action="confirm-delete" data-id="${esc(d.id)}">${t('移到最近删除','Move to deleted')}</button>`));}
function openTrash(){showModal(dialogFrame(t('最近删除','Recently deleted'),state.trash.length?`<p class="muted">${t('恢复后会回到设备库，购买记录和每日价值保持不变。','Restored devices return to your library with their original purchase details and daily value.')}</p><div class="trash-list">${state.trash.slice(0,50).map(d=>`<div class="trash-row"><div class="od-field od-fill"><strong>${esc(d.name)}</strong><small>${money(d.price,d.currency)} · ${date(d.date)}</small></div><button class="button" data-action="restore" data-id="${esc(d.id)}">${t('恢复','Restore')}</button></div>`).join('')}</div>${state.trash.length>50?`<p class="muted">${t('每次显示前 50 条，恢复后可继续查看。全部记录均包含在备份中。','Showing the first 50 records. Restore them to see more; backups include all records.')}</p>`:''}`:`<p class="muted">${t('没有待恢复的设备。','No devices to restore.')}</p>`));}
function exportDownload(data,filename){try{const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);notify(t('已发起备份下载，请确认浏览器已保存文件。','Backup download requested. Confirm your browser saved the file.'));}catch(e){notify(t('无法下载备份，请使用自动化接口读取备份内容。','Download is unavailable. Read the backup through the automation API.'));}}
async function chooseBackup(file){
  if(!file)return;if(file.size>5*1024*1024){notify(t('备份不能超过 5 MB，当前数据未改变。','Backups must be 5 MB or smaller. Your data has not changed.'));return;}
  pendingFile=file;showModal(dialogFrame(t('检查备份','Checking backup'),`<p class="muted">${t('正在读取并校验备份…','Reading and validating the backup…')}</p>`));const modal=$('#modal');
  try{const text=await file.text();if(!modal.open||pendingFile!==file)return;const backup=JSON.parse(text),result=model.preview({action:'import',backup});if(!result.ok)throw new Error(result.error.code);importPlan=result.data;const e=result.data.effect;modal.innerHTML=dialogFrame(t('确认恢复备份','Review backup restore'),`<p class="muted backup-file">${esc(file.name)}</p><div class="restore-summary"><div class="od-stat"><strong>${number(e.replaceCount)}</strong><span>${t('当前设备将被替换','Current devices replaced')}</span></div><div class="od-stat"><strong>${number(e.importCount)}</strong><span>${t('备份中的设备','Devices in backup')}</span></div><div class="od-stat"><strong>${number(e.trashCount)}</strong><span>${t('可恢复的删除记录','Deleted records included')}</span></div></div><p class="muted">${t('语言、外观与默认货币也会恢复。自动化写入许可不会随备份开启。','Language, appearance, and default currency will also be restored. Backup data cannot enable automation writes.')}</p><p class="dialog-description">${t('恢复会替换当前记录。建议先导出当前备份再继续。','Restoring replaces current records. Export your current data before proceeding.')}</p><div id="import-error" class="dialog-error" role="alert" hidden></div>`,`<button class="button" data-action="export">${t('先备份当前数据','Back up current data')}</button><button class="button" data-action="close-modal">${t('取消','Cancel')}</button><button class="button primary" data-action="confirm-import">${t('确认恢复','Restore backup')}</button>`);modal.querySelector('[data-action="close-modal"]').focus();}
  catch(e){if(!modal.open||pendingFile!==file)return;modal.innerHTML=dialogFrame(t('备份未导入','Backup not imported'),`<p class="field-error">${esc(errorText('INVALID_BACKUP'))}</p>`,`<button class="button" data-action="close-modal">${t('返回','Go back')}</button>`);}
}
function openHelp(){showModal(dialogFrame(t('关于这份原型','About this prototype'),`<h3>${t('用得越久，每天越轻','More days. Less per day.')}</h3><p>${t('每日成本 = 购买价格 ÷ 持有天数。回本仅代表个人使用价值达到购买价格，不代表收入或折旧。','Daily cost = purchase price ÷ days owned. The value goal reflects personal use, not income or depreciation.')}</p><h3>${t('当前可以体验','Available in this prototype')}</h3><p>${t('设备记录、中英文、外观、备份恢复、最近删除以及页面内的结构化自动化。','Device records, Chinese and English, appearance, backups and restore, recently deleted records, and structured in-page automation.')}</p><h3>${t('仍未接入','Not connected')}</h3><p>${t('真实跨设备同步、原生宿主、正式产品 CLI 与 MCP 服务均不包含在本原型中。','Real sync, native hosts, a product CLI, and an MCP server are outside this prototype.')}</p><h3>${t('数据范围','Data scope')}</h3><p>${t('默认记录是示例。主库与空库入口分别保存；备份不加密，请自行妥善保存。','Seed records are examples. The main library and empty-library entry use separate storage. Backups are unencrypted; keep them somewhere appropriate.')}</p>`,'',true));}
const agentDescribe=()=>({ok:true,data:{name:'Payback browser prototype',version:'1.0',scope:'current browser page only',transport:'window.paybackAgent',languageIndependent:true,writesEnabled:model.agentWriteEnabled(),persistence:state.storage.persistent?'browser-local':'session-only',methods:['describe()','list()','get(id)','summary(currency?)','exportBackup()','preview(request)','commit(token)'],actions:['create','update','delete','restore','preferences','import'],deviceFields:{id:'stable string; generated on create',name:'string, 1..120 characters',price:'number > 0, <= 10000000, <= 2 decimal places',daily:'same as price, or null',date:'YYYY-MM-DD, 1900-01-01..today',currency:model.currencies,category:model.categories,note:'string <= 2000 characters'},writeFlow:'Enable writes in Settings. preview(request) makes no changes. Review effect, then commit(data.token) within 5 minutes. Token is revision-bound and reusable idempotently for the latest 100 commits.',limitations:['No HTTP endpoint, CLI, MCP, or authentication boundary','Same-page scripts can access this API','Permissions reset on reload and are never exported','No real sync, income, exchange-rate conversion, or encryption']}});
window.paybackAgent=Object.freeze({
  describe:agentDescribe,
  list:()=>({ok:true,data:model.snapshot().devices.map(d=>({...d,metrics:model.metrics(d)}))}),
  get:id=>{const d=model.snapshot().devices.find(x=>x.id===id);return d?{ok:true,data:{...d,metrics:model.metrics(d)}}:{ok:false,error:{code:'NOT_FOUND'}};},
  summary:(currency=state.preferences.currency)=>{if(!model.currencies.includes(currency))return{ok:false,error:{code:'INVALID_CURRENCY'}};const list=model.snapshot().devices.filter(d=>d.currency===currency);return{ok:true,data:{currency,count:list.length,investment:list.reduce((a,d)=>a+d.price,0),dailyCost:list.reduce((a,d)=>a+model.metrics(d).cost,0),revision:model.snapshot().revision}};},
  exportBackup:()=>({ok:true,data:model.backup()}),
  preview:request=>{if($('#modal').open)return{ok:false,error:{code:'BUSY'}};return model.preview(request);},
  commit:token=>{if(!model.agentWriteEnabled())return{ok:false,error:{code:'WRITES_DISABLED'}};if($('#modal').open||saving)return{ok:false,error:{code:'BUSY'}};const result=model.commit(token);if(result.ok){if(result.data.selectedId)selected=result.data.selectedId;refresh();notify(t('自动化变更已应用','Automation change applied')+' · '+storageMessage());}return result;}
});
function openAgentHelp(){agentExample=null;showModal(dialogFrame(t('自动化调用说明','Automation API guide'),`<p>${t('支持执行页面脚本的 agent，可直接读取当前页面的结构化接口。此处不是终端命令。','Agents that can execute page scripts can call this structured interface directly. These are page scripts, not terminal commands.')}</p><h3>${t('读取设备与接口','Read devices and capabilities')}</h3><pre><code>window.paybackAgent.describe()
window.paybackAgent.list()
window.paybackAgent.get("mac")
window.paybackAgent.summary("CNY")</code></pre><button class="button" data-action="agent-query">${t('运行只读查询','Run read-only query')}</button><pre id="agent-output" hidden></pre><h3>${t('先预览，再提交','Preview, then commit')}</h3><pre><code>const p = window.paybackAgent.preview({
  action: "update",
  id: "mac",
  patch: { daily: 25 }
})
// Review p.data.effect, then explicitly commit:
window.paybackAgent.commit(p.data.token)</code></pre><p>${t('写入默认关闭。预览不会修改数据；预览 5 分钟有效，期间任何数据修改都会使旧预览失效。重复提交同一个已完成标识不会重复创建记录。','Writes are off by default. Preview never changes data. Tokens expire after 5 minutes and become stale after another mutation. Repeating a completed token does not create duplicate records.')}</p><h3>${t('稳定返回结构','Stable response format')}</h3><pre><code>{ ok: true, data: { ... } }
{ ok: false, error: { code: "STALE_PREVIEW" } }</code></pre><p>${t('新增、编辑、删除、恢复、偏好与备份恢复均使用与界面相同的校验和状态。删除可恢复。完整字段约束由 describe() 返回。','Create, update, delete, restore, preferences, and backup import use the same validation and state as the interface. Deletes are recoverable. describe() returns field constraints.')}</p><p>${t('这是同一页面内的便利接口，不是权限隔离。正式产品仍需独立引擎、CLI / MCP、授权与审计。','This is a convenience API within one page, not an access-control boundary. A production product still needs its engine, CLI / MCP, authorization, and audit mechanisms.')}</p>`,'',true));}
function updatePreference(p,focusId){const result=execute({action:'preferences',preferences:p});if(!result.ok){notify(errorText(result.error.code));refresh();return;}refresh();if(focusId)$('#'+focusId)?.focus();notify(t('偏好已更新','Preferences updated')+' · '+storageMessage());}
document.body.insertAdjacentHTML('beforeend','<dialog id="modal" aria-labelledby="modal-title"></dialog><input id="backup-file" type="file" accept=".json,application/json" hidden><div class="toast" id="toast" role="status" aria-live="polite" hidden></div>');
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('submit',e=>{if(e.target.id==='device-form')e.preventDefault();});
document.addEventListener('focusout',e=>{if(e.target.closest('#device-form')&&['name','price','daily','date','note'].includes(e.target.id))validateEditor(e.target.id);});
// Clear corrected field errors while typing so blur cannot move the Save button under the pointer.
document.addEventListener('input',e=>{if(e.target.closest('#device-form')&&e.target.getAttribute('aria-invalid')==='true')validateEditor(e.target.id);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.closest('#device-form')&&!['TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)){e.preventDefault();saveEditor();}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='sort'){sort=e.target.value;limit=50;renderSidebar();$('#sort').focus();}if(id==='goal-enabled'){$('#daily-field').hidden=!e.target.checked;if(e.target.checked)$('#daily').focus();}if(id==='language')updatePreference({language:e.target.value},id);if(id==='appearance')updatePreference({theme:e.target.value},id);if(id==='default-currency')updatePreference({currency:e.target.value},id);if(id==='automation-enabled'){model.enableAutomation(e.target.checked);state=model.snapshot();notify(e.target.checked?t('自动化写入已开启，仅本次页面有效','Automation writes enabled for this page session'):t('自动化写入已关闭','Automation writes disabled'));}if(id==='backup-file'){const file=e.target.files[0];e.target.value='';chooseBackup(file);}});
document.addEventListener('click',e=>{
  const device=e.target.closest('[data-device]');if(device){selected=device.dataset.device;view='devices';mobile='detail';render();if(innerWidth<768)focusMain();else [...document.querySelectorAll('[data-device]')].find(n=>n.dataset.device===selected)?.focus();return;}
  const trigger=e.target.closest('[data-action]');if(!trigger)return;const action=trigger.dataset.action;
  if(action==='settings'){view='settings';render();focusMain();}
  else if(action==='back'){view='devices';mobile='list';render();[...document.querySelectorAll('[data-device]')].find(n=>n.dataset.device===selected)?.focus();}
  else if(action==='add')openEditor();
  else if(action==='edit')openEditor(current());
  else if(action==='more'){limit+=50;renderSidebar();$('[data-action="more"]')?.focus();}
  else if(action==='theme')updatePreference({theme:document.documentElement.classList.contains('dark')?'light':'dark'});
  else if(action==='close-modal')closeModal();
  else if(action==='save')saveEditor();
  else if(action==='help')openHelp();
  else if(action==='delete')openDelete();
  else if(action==='confirm-delete'){
    const id=trigger.dataset.id,result=execute({action:'delete',id});if(!result.ok){notify(errorText(result.error.code));return;}lastDeleted=id;selected=result.data.selectedId;closeModal();refresh();focusMain();notify(t('设备已移到最近删除','Device moved to Recently deleted')+' · '+storageMessage(),true);
  }
  else if(action==='undo'&&lastDeleted){const result=execute({action:'restore',id:lastDeleted});if(handleResult(result,t('已恢复设备','Device restored'))){lastDeleted=null;view='devices';mobile='detail';render();focusMain();}}
  else if(action==='trash')openTrash();
  else if(action==='restore'){const result=execute({action:'restore',id:trigger.dataset.id});if(!result.ok){notify(errorText(result.error.code));return;}sync();render();openTrashContent();notify(t('设备已恢复','Device restored')+' · '+storageMessage());}
  else if(action==='export')exportDownload(model.backup(),`payback-backup-${model.today()}.json`);
  else if(action==='export-original')exportDownload(model.original()||'',`payback-original-${model.today()}.json`);
  else if(action==='import')$('#backup-file').click();
  else if(action==='confirm-import'&&importPlan){const result=model.commit(importPlan.token);if(!result.ok){$('#import-error').textContent=errorText(result.error.code);$('#import-error').hidden=false;return;}selected=result.data.selectedId;model.enableAutomation(false);closeModal();refresh();focusMain();notify(t('备份已恢复','Backup restored')+' · '+storageMessage());}
  else if(action==='agent-help')openAgentHelp();
  else if(action==='agent-query'){const out=$('#agent-output');out.textContent=JSON.stringify(window.paybackAgent.summary(),null,2);out.hidden=false;}
});
function openTrashContent(){const modal=$('#modal');modal.close();openTrash();}
refresh();if(page==='form')openEditor();
})();
